import json
import os
import sys
from datetime import datetime

def parse_date(date_str):
    if not date_str or date_str.strip() == "" or date_str.lower() == "n/a":
        return None
    # Try YYYYMMDD
    try:
        return datetime.strptime(date_str, "%Y%m%d")
    except ValueError:
        pass
    # Try MM/DD/YYYY
    try:
        return datetime.strptime(date_str, "%m/%d/%Y")
    except ValueError:
        pass
    return None

def solve():
    if len(sys.argv) < 3:
        return

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load all JSON files in the directory
    records_by_recall = {}
    for filename in os.listdir(packet_dir):
        if filename.endswith(".json"):
            file_base = os.path.splitext(filename)[0]
            with open(os.path.join(packet_dir, filename), 'r') as f:
                try:
                    data = json.load(f)
                    for result in data.get("results", []):
                        recall_num = result.get("recall_number")
                        if recall_num:
                            if recall_num not in records_by_recall:
                                records_by_recall[recall_num] = []
                            records_by_recall[recall_num].append({
                                "data": result,
                                "doc": file_base
                            })
                except json.JSONDecodeError:
                    continue

    output = {}

    for pair_str in manifest.get("pairs", []):
        rule_id, entity = pair_str.split("::")
        facts_needed = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}

        # Find all records for this entity (recall_number)
        entity_records = records_by_recall.get(entity, [])

        for fact_name in facts_needed:
            # Map fact name to field name
            field_map = {
                "initiation date": "recall_initiation_date",
                "classification date": "center_classification_date",
                "termination date": "termination_date"
            }
            field_name = field_map.get(fact_name)

            if not field_name:
                pair_result[fact_name] = "ABSENT"
                continue

            values = []
            for rec in entity_records:
                val = rec["data"].get(field_name)
                if val is not None and str(val).strip() != "":
                    values.append((val, rec["doc"]))

            if not values:
                pair_result[fact_name] = "ABSENT"
            elif len(set(v[0] for v in values)) > 1:
                # Check if they are actually different values
                # We use string representation to check for conflict
                unique_vals = []
                for v, d in values:
                    if v not in unique_vals:
                        unique_vals.append(v)
                if len(unique_vals) > 1:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [str(values[0][0]), values[0][1]]
            else:
                # Single unique value
                val, doc = values[0]
                # Format date if it's a date string in YYYYMMDD
                if field_name in ["recall_initiation_date", "center_classification_date", "termination_date"]:
                    dt = parse_date(str(val))
                    if dt:
                        val = dt.strftime("%Y-%m-%d")
                pair_result[fact_name] = [str(val), doc]

        output[pair_str] = pair_result

    print(json.dumps(output))

if __name__ == "__main__":
    solve()

